create table client_requests (
    requestor                  varchar2(100 char),
    approver                   varchar2(100 char),
    id                         number
        generated by default on null as identity
    not null enable,
    status                     varchar2(50 byte) default 'new',
    comments                   varchar2(200 byte),
    submission_date            date,
    account_associate          varchar2(100 byte),
    account_manager            varchar2(100 byte),
    is_new_edi_setup           varchar2(50 byte),
    account_request_type       varchar2(50 byte),
    ccode_request_type         varchar2(50 byte),
    duke_request_type          varchar2(50 byte),
    account_name               varchar2(100 byte),
    legal_name                 varchar2(100 byte),
    dba                        varchar2(100 byte),
    aka                        varchar2(100 byte),
    fka                        varchar2(100 byte),
    phone                      varchar2(12 byte),
    fax                        varchar2(12 byte),
    website                    varchar2(100 byte),
    physical_address           varchar2(100 byte),
    physical_add_city          varchar2(50 byte),
    physical_add_state         varchar2(50 byte),
    physical_add_zip           number,
    business_type              varchar2(50 byte),
    ccode_name                 varchar2(100 byte),
    "GROUP"                    varchar2(50 byte),
    line_of_business           varchar2(50 byte),
    qualified_health_plan      varchar2(50 byte),
    ccode_effective_date       varchar2(50 byte),
    ccode                      varchar2(50 byte),
    account_no                 varchar2(50 byte),
    sutter_access_level        varchar2(50 byte),
    eclient_id                 varchar2(50 byte),
    eligibility                number,
    business_unit              varchar2(50 byte),
    hst_effective_date         date,
    special_access             varchar2(400 byte),
    benchmark_pricing          varchar2(50 byte),
    billing_type               varchar2(50 byte),
    invoice_report             varchar2(50 byte),
    invoice_media              varchar2(50 byte),
    invoice_rollup_level       varchar2(50 byte),
    setup_type                 varchar2(10 byte),
    licensed_state             varchar2(50 byte),
    networx_account            varchar2(20 byte),
    master_account_id          number,
    term_date                  date,
    repricing_methods          varchar2(50 byte),
    summary_rollup_level       varchar2(50 byte),
    contacts_config            varchar2(50 byte),
    cdm_comments               varchar2(200 byte),
    edi_comments               varchar2(200 byte),
    special_provider_access    varchar2(100 byte),
    case_numbers               varchar2(100 byte),
    global_access              varchar2(1 byte),
    clinical_review_access     varchar2(1 byte),
    duke_review_access         varchar2(1 byte),
    viant_access               varchar2(1 byte),
    network_claim_run_out_date date,
    oon_claim_run_out_date     date,
    acc_effective_date         date,
    bay_effective_date         date,
    bay_term_date              date,
    sut_term_date              date,
    sut_effective_date         date,
    bench_term_date            date,
    bench_effective_date       date,
    bpl                        varchar2(3 byte),
    er_inc                     varchar2(8 byte),
    ub_flag                    varchar2(8 byte),
    hcfa_flag                  varchar2(8 byte),
    ack_signed                 varchar2(3 byte),
    attestation_signed         varchar2(3 byte),
    networx_parent_id          number,
    duke_id                    number,
    parent_code                varchar2(10 byte),
    beech_migration_complete   varchar2(3 byte),
    neg_auto_deploy            varchar2(3 byte),
    "4DIGIT_ACCT"              number,
    networx_parent_code        varchar2(10 byte),
    cprc_eclientid             number,
    acc_int                    varchar2(3 byte),
    active_ccode               varchar2(3 byte),
    bay_access_level           varchar2(50 byte),
    sut_access_level           varchar2(50 byte)
);

alter table client_requests
    add constraint client_requests_pk primary key ( id )
        using index enable;


